def clamp(value, low, high):
    """Return value limited to the closed range [low, high]."""
    if not (isinstance(value, (int, float)) and isinstance(low, (int, float)) and isinstance(high, (int, float))):
        raise TypeError("All inputs must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")
    if value < low:
        return low
    if value > high:
        return high
    return value
